API Gateway / Ingestion Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("API Gateway / Ingestion Container", "API Gateway / Ingestion Container") {
    Component("AWS_API_Gateway_Envoy_proxy", "AWS API Gateway & Envoy proxy", "AWS API Gateway & Envoy proxy", "Serves as the secure edge proxy handling external ingress, request validation, edge routing, circuit breaking, and low-latency gRPC connection pooling.")
    Component("Protocol_Buffers_Serializer", "Protocol Buffers Serializer", "Protocol Buffers", "Minimizes serialization overhead for validated payloads to meet the 50 ms P99 latency target.")
    Component("W3C_Trace_Context_AWS_X_Ray", "W3C Trace Context & AWS X-Ray", "W3C Trace Context & AWS X-Ray", "Enables distributed tracing for compliance and auditability.")
    Component("Idempotency_Token_Cache", "Idempotency & Token Cache", "Redis (Native Envoy Integration)", "Handles sliding-window idempotency checks and request deduplication.")
}

Rel("AWS_API_Gateway_Envoy_proxy", "Protocol_Buffers_Serializer", "Serializes validated payloads", "Protocol Buffers")
Rel("AWS_API_Gateway_Envoy_proxy", "Idempotency_Token_Cache", "Performs deduplication and idempotency checks", "Internal TCP")
Rel("AWS_API_Gateway_Envoy_proxy", "W3C_Trace_Context_AWS_X_Ray", "Propagates trace context for distributed tracing", "")
@enduml

Feature Store.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Feature_Store", "Feature Store") {
    Component(In_Memory_Feature_Cache, "In-Memory Feature Cache", "AWS ElastiCache for Redis", "Provides sub-millisecond operational feature retrieval using batch pipelining and an L1 cache.")
    Component(Cold_Historical_Feature_Storage, "Cold Historical Feature Storage", "Amazon S3 / DynamoDB", "Provides fallback lookup for historical features and supports 7-year audit requirements.")
    Component(Snapshot_Publisher, "Snapshot Publisher", "AWS SDK / JSON over TLS", "Publishes immutable point-in-time feature snapshots to the async event bus.")
}

Rel(In_Memory_Feature_Cache, Snapshot_Publisher, "Publishes immutable point-in-time feature snapshots", "AWS SDK / JSON over TLS")
Rel(In_Memory_Feature_Cache, Cold_Historical_Feature_Storage, "Fallback lookup for historical features", "HTTPS")

@enduml

Async Event Bus.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("async_event_bus", "Async Event Bus") {
    Component(EventPublisher, "Event Publisher", "AWS SDK", "Publishes transaction scoring events from the scoring engine to the event bus.")
    Component(EventRouter, "Event Router", "AWS EventBridge", "Routes incoming scoring events to appropriate downstream queues and targets.")
    Component(EventQueue, "Event Queue", "AWS SQS", "Queues suspicious case events and decision audit logs for asynchronous processing.")
}

Rel(EventPublisher, EventRouter, "Publishes scoring events", "AWS SDK over SQS/EventBridge")
Rel(EventRouter, EventQueue, "Dispatches events to queues", "AWS SQS/SNS")
@enduml

